        lines = lines_at_start.split('\n')
        if len(lines) < 23:
            continue

        # Extract up to 23 rows
        rows = []
        for i, line in enumerate(lines[:23]):
            line = line.strip()
            if line and line[0].isdigit():
                try:
                    rows.append([int(x) for x in line.split()])
                except ValueError:
                    break
            else:
                break

